11	/// dispatches the app-start event and routes to Home/Chat or Login once
12	/// `SessionBloc` resolves. On a network-error state, shows a visible retry
13	/// action instead of routing away — never stuck (R7; FR-010; Edge Cases).
14	class SplashPage extends StatefulWidget {
15	  const SplashPage({super.key});
16	
17	  @override
18	  State<SplashPage> createState() => _SplashPageState();
19	}
