21	class _SplashPageState extends State<SplashPage> {
22	  @override
23	  void initState() {
24	    super.initState();
25	    // Dispatched exactly once per mount — go_router may rebuild this route's
26	    // builder on ancestor rebuilds, but initState only runs once.
27	    context.read<SessionBloc>().add(const AppStarted());
28	  }
