30	  @override
31	  Widget build(BuildContext context) {
32	    return Scaffold(
33	      backgroundColor: DesignTokens.colorPrimary,
34	      body: BlocConsumer<SessionBloc, SessionStatus>(
35	        listener: (context, status) {
36	          switch (status) {
37	            case SessionStatusAuthenticated():
38	              context.push(AppRoutes.home);
39	            case SessionStatusUnauthenticated():
40	              context.push(AppRoutes.login);
41	            case SessionStatusChecking():
42	            case SessionStatusExpiredRenewable():
43	            case SessionStatusNetworkError():
44	              break;
45	          }
46	        },
