3	/// Wraps `flutter_secure_storage` for the four session fields (data-model.md
4	/// Session) — iOS Keychain-backed, never plaintext (research.md R5).
5	class SecureTokenStorage {
6	  SecureTokenStorage({FlutterSecureStorage? storage})
7	      : _storage = storage ?? const FlutterSecureStorage();
8	
9	  final FlutterSecureStorage _storage;
10	
11	  static const _accessTokenKey = 'accessToken';
12	  static const _refreshTokenKey = 'refreshToken';
13	  static const _expiresAtKey = 'expiresAt';
14	  static const _tokenTypeKey = 'tokenType';
15	
16	  Future<void> writeSession({
17	    required String accessToken,
18	    required String refreshToken,
19	    required int expiresAt,
20	    required String tokenType,
21	  }) async {
22	    await _storage.write(key: _accessTokenKey, value: accessToken);
23	    await _storage.write(key: _refreshTokenKey, value: refreshToken);
24	    await _storage.write(key: _expiresAtKey, value: expiresAt.toString());
25	    await _storage.write(key: _tokenTypeKey, value: tokenType);
26	  }
27	
28	  Future<String?> readAccessToken() => _storage.read(key: _accessTokenKey);
29	
30	  Future<String?> readRefreshToken() => _storage.read(key: _refreshTokenKey);
31	
32	  Future<int?> readExpiresAt() async {
33	    final raw = await _storage.read(key: _expiresAtKey);
34	    return raw == null ? null : int.tryParse(raw);
